# Try all plausible n=6 displacements that keep the duplicate in bounds
def make_solution(n6_disp, fill_mode='auto'):
    """Generate solution with given n=6 displacement"""
    result = [[0]*11 for _ in range(11)]

    # Specials from test input
    specials = [
        (2, 1, 1),   # n=1
        (6, 7, 2),   # n=2
        (7, 5, 6),   # n=6
        (7, 9, 3)    # n=3
    ]

    # Known displacements
    known_displacements = {
        1: (-1, 2),
        2: (0, -4),
        3: (3, 0)
    }
    n6_disp_val = n6_disp

    # Place all values + duplicates
    for r, c, val in specials:
        result[r][c] = val

        if val == 1:
            dr, dc = -1, 2
            nr, nc = r + dr, c + dc
            if 0 <= nr < 11 and 0 <= nc < 11:
                result[nr][nc] = 1

        elif val == 2:
            dr, dc = 0, -4
            nr, nc = r + dr, c + dc
            if 0 <= nr < 11 and 0 <= nc < 11:
                result[nr][nc] = 2

        elif val == 3:
            dr, dc = 3, 0
            nr, nc = r + dr, c + dc
            if 0 <= nr < 11 and 0 <= nc < 11:
                result[nr][nc] = 3

        else:  # val == 6
            dr, dc = n6_disp
            nr, nc = r + dr, c + dc
            if 0 <= nr < 11 and 0 <= nc < 11:
                result[nr][nc] = 6

    # Apply fills
    for r, c, val in specials:
        if val == 1:
            dr, dc = -1, 2
        elif val == 2:
            dr, dc = 0, -4
        elif val == 3:
            dr, dc = 3, 0
        else:
            dr, dc = n6_disp

        if dr == 0:
            # Pure horizontal
            start, end = min(c, c+dc), max(c, c+dc)
            for cc in range(start, end + 1):
                if result[r][cc] == 0:
                    result[r][cc] = 5
        elif dc == 0:
            # Pure vertical
            start, end = min(r, r+dr), max(r, r+dr)
            for rr in range(start, end + 1):
                if result[rr][c] == 0:
                    result[rr][c] = 5
        else:
            # Diagonal: horizontal fill if |dr|<=|dc|
