        nr, nc = r + dr, c + dc

        # Fill along the primary axis direction
        if dr == 0:  # Pure horizontal fill
            start, end = min(c, c+dc), max(c, c+dc)
            for cc in range(start, end + 1):
                if 0 <= r < 11 and 0 <= cc < 11 and result[r][cc] == 0:
                    result[r][cc] = 5
