            start, end = min(r, r+dr), max(r, r+dr)
            for rr in range(start, end + 1):
                if 0 <= rr < 11 and 0 <= c < 11 and result[rr][c] == 0:
                    result[rr][c] = 5
        else:  # Diagonal-ish, fill horizontally if |dr|<=|dc|
            if abs(dr) <= abs(dc):
                start, end = min(c, c+dc), max(c, c+dc)
                for cc in range(start, end + 1):
                    if 0 <= r < 11 and 0 <= cc < 11 and result[r][cc] == 0:
                        result[r][cc] = 5

        if 0 <= nr < 11 and 0 <= nc < 11:
            result[nr][nc] = val

    return result

